mkitem!{mkstruct!{# [doc = " The MIR type checker. Visits the MIR and enforces all the"] # [doc = " constraints needed for it to be valid and well-typed. Along the"] # [doc = " way, it accrues region constraints -- these can later be used by"] # [doc = " NLL region checking."] struct TypeChecker < 'a , 'tcx > { root_cx : & 'a mut BorrowCheckRootCtxt < 'tcx > , infcx : & 'a BorrowckInferCtxt < 'tcx > , last_span : Span , body : & 'a Body < 'tcx > , # [doc = " The bodies of all promoteds. As promoteds have a completely separate CFG"] # [doc = " recursing into them may corrupt your data structures if you're not careful."] promoted : & 'a IndexSlice < Promoted , Body < 'tcx > > , # [doc = " User type annotations are shared between the main MIR and the MIR of"] # [doc = " all of the promoted items."] user_type_annotations : & 'a CanonicalUserTypeAnnotations < 'tcx > , region_bound_pairs : & 'a RegionBoundPairs < 'tcx > , known_type_outlives_obligations : & 'a [ty :: PolyTypeOutlivesPredicate < 'tcx >] , reported_errors : FxIndexSet < (Ty < 'tcx > , Span) > , universal_regions : & 'a UniversalRegions < 'tcx > , location_table : & 'a PoloniusLocationTable , polonius_facts : & 'a mut Option < PoloniusFacts > , borrow_set : & 'a BorrowSet < 'tcx > , constraints : & 'a mut MirTypeckRegionConstraints < 'tcx > , deferred_closure_requirements : & 'a mut DeferredClosureRequirements < 'tcx > , # [doc = " When using `-Zpolonius=next`, the liveness helper data used to create polonius constraints."] polonius_liveness : Option < PoloniusLivenessContext > , }}}
mkitem!{mkstruct!{# [doc = " Holder struct for passing results from MIR typeck to the rest of the non-lexical regions"] # [doc = " inference computation."] pub (crate) struct MirTypeckResults < 'tcx > { pub (crate) constraints : MirTypeckRegionConstraints < 'tcx > , pub (crate) universal_region_relations : Frozen < UniversalRegionRelations < 'tcx > > , pub (crate) region_bound_pairs : Frozen < RegionBoundPairs < 'tcx > > , pub (crate) known_type_outlives_obligations : Frozen < Vec < ty :: PolyTypeOutlivesPredicate < 'tcx > > > , pub (crate) deferred_closure_requirements : DeferredClosureRequirements < 'tcx > , pub (crate) polonius_context : Option < PoloniusContext > , }}}
mkitem!{mkstruct!{# [doc = " A collection of region constraints that must be satisfied for the"] # [doc = " program to be considered well-typed."] # [derive (Clone)] pub (crate) struct MirTypeckRegionConstraints < 'tcx > { # [doc = " Maps from a `ty::Placeholder` to the corresponding"] # [doc = " `PlaceholderIndex` bit that we will use for it."] # [doc = ""] # [doc = " To keep everything in sync, do not insert this set"] # [doc = " directly. Instead, use the `placeholder_region` helper."] pub (crate) placeholder_indices : PlaceholderIndices , # [doc = " Each time we add a placeholder to `placeholder_indices`, we"] # [doc = " also create a corresponding \"representative\" region vid for"] # [doc = " that wraps it. This vector tracks those. This way, when we"] # [doc = " convert the same `ty::RePlaceholder(p)` twice, we can map to"] # [doc = " the same underlying `RegionVid`."] pub (crate) placeholder_index_to_region : IndexVec < PlaceholderIndex , ty :: Region < 'tcx > > , # [doc = " In general, the type-checker is not responsible for enforcing"] # [doc = " liveness constraints; this job falls to the region inferencer,"] # [doc = " which performs a liveness analysis. However, in some limited"] # [doc = " cases, the MIR type-checker creates temporary regions that do"] # [doc = " not otherwise appear in the MIR -- in particular, the"] # [doc = " late-bound regions that it instantiates at call-sites -- and"] # [doc = " hence it must report on their liveness constraints."] pub (crate) liveness_constraints : LivenessValues , pub (crate) outlives_constraints : OutlivesConstraintSet < 'tcx > , pub (crate) universe_causes : FxIndexMap < ty :: UniverseIndex , UniverseInfo < 'tcx > > , pub (crate) type_tests : Vec < TypeTest < 'tcx > > , }}}
mkitem!{mkimpl!{impl < 'tcx > MirTypeckRegionConstraints < 'tcx > { # [doc = " Creates a `Region` for a given `PlaceholderRegion`, or returns the"] # [doc = " region that corresponds to a previously created one."] pub (crate) fn placeholder_region (& mut self , infcx : & InferCtxt < 'tcx > , placeholder : ty :: PlaceholderRegion ,) -> ty :: Region < 'tcx > { let placeholder_index = self . placeholder_indices . insert (placeholder) ; match self . placeholder_index_to_region . get (placeholder_index) { Some (& v) => v , None => { let origin = NllRegionVariableOrigin :: Placeholder (placeholder) ; let region = infcx . next_nll_region_var_in_universe (origin , placeholder . universe) ; self . placeholder_index_to_region . push (region) ; region } } } }}}
mkitem!{mkenum!{# [doc = " The `Locations` type summarizes *where* region constraints are"] # [doc = " required to hold. Normally, this is at a particular point which"] # [doc = " created the obligation, but for constraints that the user gave, we"] # [doc = " want the constraint to hold at all points."] # [derive (Copy , Clone , PartialEq , Eq , PartialOrd , Ord , Hash , Debug)] pub enum Locations { # [doc = " Indicates that a type constraint should always be true. This"] # [doc = " is particularly important in the new borrowck analysis for"] # [doc = " things like the type of the return slot. Consider this"] # [doc = " example:"] # [doc = ""] # [doc = " ```compile_fail,E0515"] # [doc = " fn foo<'a>(x: &'a u32) -> &'a u32 {"] # [doc = "     let y = 22;"] # [doc = "     return &y; // error"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " Here, we wind up with the signature from the return type being"] # [doc = " something like `&'1 u32` where `'1` is a universal region. But"] # [doc = " the type of the return slot `_0` is something like `&'2 u32`"] # [doc = " where `'2` is an existential region variable. The type checker"] # [doc = " requires that `&'2 u32 = &'1 u32` -- but at what point? In the"] # [doc = " older NLL analysis, we required this only at the entry point"] # [doc = " to the function. By the nature of the constraints, this wound"] # [doc = " up propagating to all points reachable from start (because"] # [doc = " `'1` -- as a universal region -- is live everywhere). In the"] # [doc = " newer analysis, though, this doesn't work: `_0` is considered"] # [doc = " dead at the start (it has no usable value) and hence this type"] # [doc = " equality is basically a no-op. Then, later on, when we do `_0"] # [doc = " = &'3 y`, that region `'3` never winds up related to the"] # [doc = " universal region `'1` and hence no error occurs. Therefore, we"] # [doc = " use Locations::All instead, which ensures that the `'1` and"] # [doc = " `'2` are equal everything. We also use this for other"] # [doc = " user-given type annotations; e.g., if the user wrote `let mut"] # [doc = " x: &'static u32 = ...`, we would ensure that all values"] # [doc = " assigned to `x` are of `'static` lifetime."] # [doc = ""] # [doc = " The span points to the place the constraint arose. For example,"] # [doc = " it points to the type in a user-given type annotation. If"] # [doc = " there's no sensible span then it's DUMMY_SP."] All (Span) , # [doc = " An outlives constraint that only has to hold at a single location,"] # [doc = " usually it represents a point where references flow from one spot to"] # [doc = " another (e.g., `x = y`)"] Single (Location) , }}}
mkitem!{mkimpl!{impl Locations { pub fn from_location (& self) -> Option < Location > { match self { Locations :: All (_) => None , Locations :: Single (from_location) => Some (* from_location) , } } # [doc = " Gets a span representing the location."] pub fn span (& self , body : & Body < '_ >) -> Span { match self { Locations :: All (span) => * span , Locations :: Single (l) => body . source_info (* l) . span , } } }}}
